/**
 * The widget's capture card (Android). `android/` is regenerated by `expo prebuild`, so everything the card
 * needs natively is injected here:
 *
 * - `WidgetActionsActivity`: a second ReactActivity (JS component "WidgetActions") that opens over the
 *   home screen with a transparent window. The widget's Add / Scan / Gallery / Voice buttons send
 *   `dimecard://<mode>`; MainActivity claims `dime://`, so the card has its own scheme.
 * - Its manifest entry and the translucent `Theme.Dime.WidgetActions`.
 * - MainActivity also handles font scale, density, locale and layout direction changes itself, so the
 *   activity is not recreated (which showed the splash again).
 * - A night-aware window background, so a dark start never flashes the light colour. The status bar is
 *   transparent (`androidStatusBar.translucent` in app.json), so it needs no colour of its own.
 */
const fs = require("fs");
const path = require("path");
const {
  AndroidConfig,
  withAndroidColorsNight,
  withAndroidManifest,
  withAndroidStyles,
  withDangerousMod,
} = require("expo/config-plugins");

const ACTIVITY_NAME = ".WidgetActionsActivity";
const THEME_NAME = "Theme.Dime.WidgetActions";
const CARD_SCHEME = "dimecard";
/** Same dark colour as the dark splash (`expo-splash-screen` `dark.backgroundColor` in app.json). */
const DARK_BACKGROUND = "#121214";

const MAIN_ACTIVITY_EXTRA_CONFIG_CHANGES = [
  "fontScale",
  "density",
  "locale",
  "layoutDirection",
  "smallestScreenSize",
];
const MAIN_ACTIVITY_CONFIG_CHANGES = [
  "keyboard",
  "keyboardHidden",
  "orientation",
  "screenSize",
  "screenLayout",
  "uiMode",
  ...MAIN_ACTIVITY_EXTRA_CONFIG_CHANGES,
];

/** Pure (exported for tests): `|`-joined `configChanges` with `extra` added, in a stable order. */
function mergeConfigChanges(current, extra) {
  const parts = new Set((current || "").split("|").filter(Boolean));
  for (const part of extra) {
    parts.add(part);
  }
  return Array.from(parts).join("|");
}

/** Pure (exported for tests): the Kotlin source of the card activity. */
function widgetActionsActivitySource(packageName) {
  return `package ${packageName}

import android.content.Intent
import android.os.Bundle

import com.facebook.react.ReactActivity
import com.facebook.react.ReactActivityDelegate
import com.facebook.react.defaults.DefaultNewArchitectureEntryPoint.fabricEnabled
import com.facebook.react.defaults.DefaultReactActivityDelegate

import expo.modules.ReactActivityDelegateWrapper

/**
 * The widget's capture card: Add (a small quick-add card), Scan, Gallery and Voice (a floating pill)
 * open here over the home screen, without the full app. JS component "WidgetActions" reads the mode
 * from the launch URL ("${CARD_SCHEME}://<mode>"). Generated by plugins/withWidgetActions.js; do not edit.
 */
class WidgetActionsActivity : ReactActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(null)
    applyDim(intent)
  }

  // singleTask: a tap on another button while the card is open arrives here, not in onCreate.
  override fun onNewIntent(intent: Intent) {
    super.onNewIntent(intent)
    applyDim(intent)
  }

  /** Only the quick-add card dims the home screen behind it; the pill modes leave it as it is. */
  private fun applyDim(intent: Intent?) {
    val mode = intent?.data?.host
    window.setDimAmount(if (mode == null || mode == "add") 0.5f else 0f)
  }

  override fun getMainComponentName(): String = "WidgetActions"

  override fun createReactActivityDelegate(): ReactActivityDelegate {
    return ReactActivityDelegateWrapper(
          this,
          BuildConfig.IS_NEW_ARCHITECTURE_ENABLED,
          object : DefaultReactActivityDelegate(
              this,
              mainComponentName,
              fabricEnabled
          ){})
  }

  // Back closes the card and returns to the home screen. JS never sees it: the JS runtime is shared
  // with the main app, whose own back handlers must not answer for the card.
  @Suppress("OVERRIDE_DEPRECATION")
  override fun onBackPressed() {
    finish()
  }

  override fun invokeDefaultOnBackPressed() {
    finish()
  }
}
`;
}

function activityEntry(packageName) {
  return {
    $: {
      "android:name": ACTIVITY_NAME,
      "android:exported": "true",
      "android:launchMode": "singleTask",
      "android:taskAffinity": `${packageName}.widgetactions`,
      "android:excludeFromRecents": "true",
      "android:windowSoftInputMode": "adjustResize",
      "android:configChanges": MAIN_ACTIVITY_CONFIG_CHANGES.join("|"),
      "android:theme": `@style/${THEME_NAME}`,
    },
    "intent-filter": [
      {
        action: [{ $: { "android:name": "android.intent.action.VIEW" } }],
        category: [
          // Not BROWSABLE: a web page must not be able to open the card. The launcher's link needs only DEFAULT.
          { $: { "android:name": "android.intent.category.DEFAULT" } },
        ],
        data: [{ $: { "android:scheme": CARD_SCHEME } }],
      },
    ],
  };
}

/** Pure (exported for tests): adds the card activity and MainActivity's extra `configChanges`. Idempotent. */
function applyManifest(manifest, packageName) {
  const application = manifest.manifest.application?.[0];
  if (!application) {
    throw new Error("withWidgetActions: AndroidManifest.xml has no <application>");
  }
  const activities = (application.activity = application.activity || []);

  const main = activities.find((activity) => activity.$["android:name"] === ".MainActivity");
  if (!main) {
    throw new Error("withWidgetActions: MainActivity not found in AndroidManifest.xml");
  }
  main.$["android:configChanges"] = mergeConfigChanges(
    main.$["android:configChanges"],
    MAIN_ACTIVITY_EXTRA_CONFIG_CHANGES,
  );

  const existing = activities.findIndex((activity) => activity.$["android:name"] === ACTIVITY_NAME);
  if (existing >= 0) {
    activities[existing] = activityEntry(packageName);
  } else {
    activities.push(activityEntry(packageName));
  }
  return manifest;
}

const THEME_ITEMS = [
  ["android:windowIsTranslucent", "true"],
  ["android:windowBackground", "@android:color/transparent"],
  ["android:windowNoTitle", "true"],
  ["android:backgroundDimEnabled", "true"],
  ["android:windowAnimationStyle", "@android:style/Animation.Translucent"],
  ["android:editTextBackground", "@drawable/rn_edit_text_material"],
  ["colorPrimary", "@color/colorPrimary"],
];

/** Pure (exported for tests): adds the translucent card theme. Idempotent. */
function applyStyles(styles) {
  const resources = styles.resources;
  resources.style = (resources.style || []).filter((style) => style.$.name !== THEME_NAME);
  resources.style.push({
    $: { name: THEME_NAME, parent: "Theme.AppCompat.DayNight.NoActionBar" },
    item: THEME_ITEMS.map(([name, value]) => ({ $: { name }, _: value })),
  });
  return styles;
}

const withWidgetActions = (config) => {
  const packageName = config.android?.package;
  if (!packageName) {
    throw new Error("withWidgetActions: android.package must be set in app.json");
  }

  config = withAndroidManifest(config, (cfg) => {
    cfg.modResults = applyManifest(cfg.modResults, packageName);
    return cfg;
  });

  config = withAndroidStyles(config, (cfg) => {
    cfg.modResults = applyStyles(cfg.modResults);
    return cfg;
  });

  // The window behind the splash: dark at night, so a dark start never flashes the light colour.
  config = withAndroidColorsNight(config, (cfg) => {
    cfg.modResults = AndroidConfig.Colors.assignColorValue(cfg.modResults, {
      name: "activityBackground",
      value: DARK_BACKGROUND,
    });
    return cfg;
  });

  config = withDangerousMod(config, [
    "android",
    async (cfg) => {
      const dir = path.join(
        cfg.modRequest.platformProjectRoot,
        "app/src/main/java",
        ...packageName.split("."),
      );
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(
        path.join(dir, "WidgetActionsActivity.kt"),
        widgetActionsActivitySource(packageName),
      );
      return cfg;
    },
  ]);

  return config;
};

module.exports = withWidgetActions;
module.exports.mergeConfigChanges = mergeConfigChanges;
module.exports.applyManifest = applyManifest;
module.exports.applyStyles = applyStyles;
module.exports.widgetActionsActivitySource = widgetActionsActivitySource;
